for(const d of ['screenshots/representative','screenshots/core','screenshots/evidence-ventures','screenshots/legal','screenshots/zoom','screenshots/text-spacing','screenshots/forced-colors'])fs.mkdirSync(path.join(OUT,d),{recursive:true});
const fail=(scope,msg,data={})=>report.failures.push({scope,msg,...data});const ok=(c,s,m,d={})=>{if(!c)fail(s,m,d)};const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function ctxPage(browser,w,h,features=[]){const ctx=await browser.createBrowserContext();const page=await ctx.newPage();await page.setViewport({width:w,height:h,deviceScaleFactor:1});if(features.length){const cdp=await page.target().createCDPSession();await cdp.send('Emulation.setEmulatedMedia',{media:'screen',features})}const errs=[];page.on('console',m=>{if(m.type()==='error')errs.push('console:'+m.text())});page.on('pageerror',e=>errs.push('page:'+String(e)));page.on('requestfailed',r=>errs.push('request:'+r.url()+':'+(r.failure()?.errorText||'')));return{ctx,page,errs}}
async function go(page,route,wait=450){const r=await page.goto(BASE+route,{waitUntil:'load',timeout:45000});await sleep(wait);return r?.status()||0}
async function shell(page){return page.evaluate(()=>({main:document.querySelectorAll('main').length,h1:document.querySelectorAll('main h1').length,header:!!document.querySelector('header'),footer:!!document.querySelector('footer'),overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth+1,sw:document.documentElement.scrollWidth,cw:document.documentElement.clientWidth,active:document.activeElement?.tagName||null}))}
(async()=>{const browser=await puppeteer.launch({executablePath:process.env.CHROME,headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});try{
for(const route of routes)for(const [w,h] of smokeViews){const scope=`smoke:${route}:${w}x${h}`;const{ctx,page,errs}=await ctxPage(browser,w,h);let status=0;try{status=await go(page,route)}catch(e){fail(scope,'navigation failed',{error:String(e)})}const s=await shell(page);ok([200,304].includes(status),scope,'route response failed',{status});ok(s.main===1&&s.h1===1&&s.header&&s.footer,scope,'landmark/H1 shell regression',s);ok(!s.overflow,scope,'horizontal overflow',s);ok(errs.length===0,scope,'browser errors',{errs});report.smoke.push({route,w,h,status,shell:s,errors:errs,pass:!report.failures.some(f=>f.scope===scope)});await ctx.close()}
for(const route of repRoutes)for(const [w,h] of repViews){const scope=`visual:${route}:${w}x${h}`;const{ctx,page,errs}=await ctxPage(browser,w,h);await go(page,route,650);const s=await shell(page);ok(!s.overflow&&s.main===1&&s.h1===1,scope,'visual shell regression',s);ok(errs.length===0,scope,'browser errors',{errs});const f=path.join(OUT,'screenshots/representative',`${route.replace('.html','')}-${w}x${h}.png`);await page.screenshot({path:f,fullPage:true});report.representative.push({route,w,h,file:path.relative(OUT,f),pass:!report.failures.some(x=>x.scope===scope)});await ctx.close()}
const coreExpected={'urea-46.html':['min 46% wt','max 0.8% wt','max 0.55% wt','max 0.3% wt','90%'],'caustic-soda-solid.html':['1310-73-2','approx. 98.8%','99.3%','1823','Packing Group','II'],'sodium-sulphate-anhydrous.html':['99.20%','0.02%','0.30%','0.0003%','0.05%','91%']};
for(const [route,vals] of Object.entries(coreExpected)){const scope=`core:${route}`;const{ctx,page,errs}=await ctxPage(browser,390,844);await go(page,route);const d=await page.evaluate(()=>({text:document.body.innerText,reference:!!document.querySelector('[data-reference-detail="true"]'),status:document.querySelector('.reference-status')?.textContent||'',overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth+1}));ok(d.reference&&/reference detail/i.test(d.status),scope,'reference status missing',d);for(const v of vals)ok(d.text.includes(v),scope,'locked value missing',{v});ok(!d.overflow&&errs.length===0,scope,'mobile/core browser regression',{d,errs});const f=path.join(OUT,'screenshots/core',route.replace('.html','')+'.png');await page.screenshot({path:f,fullPage:true});report.core.push({route,file:path.relative(OUT,f),pass:!report.failures.some(x=>x.scope===scope)});await ctx.close()}
for(const route of ['evidence-axis.html','ventures.html']){const scope=`venture:${route}`;const{ctx,page,errs}=await ctxPage(browser,390,844);await go(page,route);const s=await shell(page);ok(!s.overflow&&errs.length===0,scope,'venture mobile regression',{s,errs});const text=await page.evaluate(()=>document.body.innerText);if(route==='evidence-axis.html')ok(/specialist venture/i.test(text),scope,'Evidence Axis status wording missing');else ok(/development-stage digital product/i.test(text),scope,'YEKI HAST status wording missing');const f=path.join(OUT,'screenshots/evidence-ventures',route.replace('.html','')+'.png');await page.screenshot({path:f,fullPage:true});report.evidenceVentures.push({route,file:path.relative(OUT,f),pass:!report.failures.some(x=>x.scope===scope)});await ctx.close()}
for(const route of ['privacy.html','legal.html']){const scope=`legal:${route}`;const{ctx,page,errs}=await ctxPage(browser,390,844);await go(page,route);const d=await page.evaluate(()=>{const ps=[...document.querySelectorAll('.legal-hero .intro,.legal-policy-section .section-cap>p,.legal-card p,.legal-split p,.legal-callout p,.legal-review-grid p,.legal-contact-panel p')].filter(e=>{const c=e.closest('#legal-contact .legal-contact-panel>div');return c?.querySelector('.legal-label')?.textContent.trim().toUpperCase()!=='LAST UPDATED'});return{minBody:Math.min(...ps.map(e=>parseFloat(getComputedStyle(e).fontSize))),overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth+1,text:document.body.innerText}});ok(d.minBody>=15.99&&!d.overflow&&errs.length===0,scope,'privacy/legal readability regression',{d,errs});if(route==='privacy.html')ok(/legal review required/i.test(d.text),scope,'privacy legal-review boundary missing');else ok(/does not add an unreviewed governing-law/i.test(d.text),scope,'legal notice boundary missing');const f=path.join(OUT,'screenshots/legal',route.replace('.html','')+'.png');await page.screenshot({path:f,fullPage:true});report.legal.push({route,minBody:d.minBody,file:path.relative(OUT,f),pass:!report.failures.some(x=>x.scope===scope)});await ctx.close()}
for(const route of zoomRoutes){const scope=`zoom:${route}`;const{ctx,page,errs}=await ctxPage(browser,720,450);await go(page,route);const d=await page.evaluate(()=>({overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth+1,cw:document.documentElement.clientWidth,sw:document.documentElement.scrollWidth,main:document.querySelectorAll('main').length,buttons:[...document.querySelectorAll('button,a[href],input,textarea,select')].filter(e=>{const r=e.getBoundingClientRect();const s=getComputedStyle(e);return s.display!=='none'&&s.visibility!=='hidden'&&r.width>0&&r.height>0}).length}));ok(!d.overflow&&d.main===1&&d.buttons>0&&errs.length===0,scope,'200% effective reflow failure',{d,errs});const f=path.join(OUT,'screenshots/zoom',route.replace('.html','')+'.png');await page.screenshot({path:f,fullPage:true});report.zoom.push({route,effectiveCssViewport:'720x450 at 1440px/200% reflow equivalent',...d,file:path.relative(OUT,f),pass:!report.failures.some(x=>x.scope===scope)});await ctx.close()}
for(const route of ['index.html','products.html','sales.html','technology.html','contact.html','privacy.html','legal.html']){const scope=`spacing:${route}`;const{ctx,page,errs}=await ctxPage(browser,390,844);await go(page,route);await page.addStyleTag({content:'p{line-height:1.5!important;margin-bottom:2em!important}body,button,input,textarea,select,a{letter-spacing:.12em!important;word-spacing:.16em!important}'});await sleep(100);const d=await page.evaluate(()=>({overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth+1,clipped:[...document.querySelectorAll('p,h1,h2,h3,button,a,input,textarea,select')].filter(e=>{const s=getComputedStyle(e);return s.overflow==='hidden'&&e.scrollHeight>e.clientHeight+2}).slice(0,10).map(e=>({tag:e.tagName,text:(e.textContent||e.value||'').trim().slice(0,60)}))}));ok(!d.overflow&&d.clipped.length===0&&errs.length===0,scope,'text-spacing clipping/overflow',{d,errs});const f=path.join(OUT,'screenshots/text-spacing',route.replace('.html','')+'.png');await page.screenshot({path:f,fullPage:true});report.textSpacing.push({route,...d,file:path.relative(OUT,f),pass:!report.failures.some(x=>x.scope===scope)});await ctx.close()}
for(const route of forcedRoutes){const scope=`forced:${route}`;const{ctx,page,errs}=await ctxPage(browser,390,844,[{name:'forced-colors',value:'active'}]);await go(page,route);const d=await page.evaluate(()=>({overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth+1,focusables:[...document.querySelectorAll('a[href],button,input,textarea,select')].filter(e=>{const r=e.getBoundingClientRect();return r.width>0&&r.height>0&&getComputedStyle(e).visibility!=='hidden'}).length}));ok(!d.overflow&&d.focusables>0&&errs.length===0,scope,'forced-colors functional smoke failed',{d,errs});const f=path.join(OUT,'screenshots/forced-colors',route.replace('.html','')+'.png');await page.screenshot({path:f,fullPage:true});report.forcedColors.push({route,...d,file:path.relative(OUT,f),pass:!report.failures.some(x=>x.scope===scope)});await ctx.close()}
for(const reduced of [true,false]){const scope=`motion:${reduced?'reduce':'normal'}`;const features=reduced?[{name:'prefers-reduced-motion',value:'reduce'}]:[];const{ctx,page,errs}=await ctxPage(browser,390,844,features);await go(page,'index.html',1800);const d=await page.evaluate(()=>{const v=document.querySelector('#holding-film');return{paused:v?.paused,currentTime:v?.currentTime,muted:v?.muted,controls:[...document.querySelectorAll('.hero-film-controls button,.hero-film-controls input')].map(e=>({name:e.getAttribute('aria-label')||e.textContent.trim(),disabled:e.disabled,hidden:!!e.closest('[hidden]')}))}});if(reduced)ok(d.paused&&d.currentTime<0.15,scope,'reduced-motion film gate changed',d);else ok(d.muted===true,scope,'normal film muted fallback changed',d);ok(errs.length===0,scope,'film browser errors',{errs});report.reducedMotion.push({reduced,...d,pass:!report.failures.some(x=>x.scope===scope)});await ctx.close()}
for(const route of routes){const scope=`keyboard-menu:${route}`;const{ctx,page,errs}=await ctxPage(browser,390,844);await go(page,route);await page.keyboard.press('Tab');const first=await page.evaluate(()=>({class:document.activeElement?.className||'',href:document.activeElement?.getAttribute('href')}));ok(String(first.class).includes('skip-link')&&first.href==='#main',scope,'skip link not first focus',{first});await page.keyboard.press('Enter');await sleep(50);const hash=await page.evaluate(()=>location.hash);ok(hash==='#main',scope,'skip link did not navigate to main',{hash});const menu=await page.$('.menu-toggle');await menu?.focus();await page.keyboard.press('Enter');await sleep(80);const opened=await page.evaluate(()=>({expanded:document.querySelector('.menu-toggle')?.getAttribute('aria-expanded'),active:document.activeElement?.textContent?.trim(),bodyInert:document.querySelector('main')?.inert}));ok(opened.expanded==='true'&&opened.bodyInert===true,scope,'compact nav did not open/inert background',opened);await page.keyboard.press('Escape');const closed=await page.evaluate(()=>({expanded:document.querySelector('.menu-toggle')?.getAttribute('aria-expanded'),focus:document.activeElement?.className||'',bodyInert:document.querySelector('main')?.inert}));ok(closed.expanded==='false'&&!closed.bodyInert&&String(closed.focus).includes('menu-toggle'),scope,'Escape/menu focus restoration failed',closed);ok(errs.length===0,scope,'keyboard browser errors',{errs});report.keyboardMenus.push({route,first,opened,closed,pass:!report.failures.some(x=>x.scope===scope)});await ctx.close()}
{const scope='rfq';const{ctx,page,errs}=await ctxPage(browser,390,844);await go(page,'sales.html');const labels=await page.evaluate(()=>[...document.querySelectorAll('#rfq-builder input,#rfq-builder textarea')].map(e=>({id:e.id,label:!!document.querySelector(`label[for="${e.id}"]`),disabled:e.disabled})));ok(labels.every(x=>x.label&&!x.disabled),scope,'RFQ label/accessibility association failed',{labels});await page.type('#rfq-product','Polypropylene');await page.type('#rfq-grade','Test Grade');await page.type('#rfq-specification','X'.repeat(250));const href=await page.$eval('#rfq-email-action',e=>e.href);ok(href.startsWith('mailto:sales@uniqueholding.com.tr?')&&decodeURIComponent(href).includes('Polypropylene')&&decodeURIComponent(href).includes('Test Grade'),scope,'RFQ mailto generation failed',{href:href.slice(0,180)});await page.click('#rfq-reset');await sleep(50);const reset=await page.$eval('#rfq-product',e=>e.value);ok(reset==='',scope,'RFQ reset failed',{reset});const d=await shell(page);ok(!d.overflow&&errs.length===0,scope,'RFQ mobile/browser regression',{d,errs});report.rfq={labels,mailtoPass:true,resetPass:reset==='',pass:!report.failures.some(x=>x.scope===scope)};await ctx.close()}
{const{ctx,page,errs}=await ctxPage(browser,390,844);await go(page,'index.html',1800);const film=await page.evaluate(()=>{const v=document.querySelector('#holding-film');const buttons=[...document.querySelectorAll('.hero-film-controls button,.hero-film-controls input')].map(e=>{const r=e.getBoundingClientRect();return{name:e.getAttribute('aria-label')||e.textContent.trim(),w:r.width,h:r.height,tabIndex:e.tabIndex}});return{paused:v?.paused,currentTime:v?.currentTime,preload:v?.preload,poster:v?.poster,buttons}});report.film={...film,lockedTouchTargets:film.buttons.filter(x=>x.w<44||x.h<44),errors:errs};await ctx.close()}
}finally{await browser.close()}
report.summary={smokeCases:report.smoke.length,smokeFailures:report.smoke.filter(x=>!x.pass).length,representativeCases:report.representative.length,representativeFailures:report.representative.filter(x=>!x.pass).length,coreCases:report.core.length,coreFailures:report.core.filter(x=>!x.pass).length,evidenceVenturesCases:report.evidenceVentures.length,evidenceVenturesFailures:report.evidenceVentures.filter(x=>!x.pass).length,legalCases:report.legal.length,legalFailures:report.legal.filter(x=>!x.pass).length,zoomCases:report.zoom.length,zoomFailures:report.zoom.filter(x=>!x.pass).length,textSpacingCases:report.textSpacing.length,textSpacingFailures:report.textSpacing.filter(x=>!x.pass).length,forcedColorsCases:report.forcedColors.length,forcedColorsFailures:report.forcedColors.filter(x=>!x.pass).length,keyboardMenuCases:report.keyboardMenus.length,keyboardMenuFailures:report.keyboardMenus.filter(x=>!x.pass).length,totalFailures:report.failures.length};fs.mkdirSync(OUT,{recursive:true});fs.writeFileSync(path.join(OUT,'phase19-regression.json'),JSON.stringify(report,null,2));console.log(JSON.stringify(report.summary,null,2));if(report.failures.length){console.error(JSON.stringify(report.failures,null,2));process.exit(1)}console.log('PHASE 19 BROWSER REGRESSION PASS');})();